    df['recuperado_1'] = (df['media_1'] < 7.0) & (df['final_1'] >= 7.0)
    df['recuperado_2'] = (df['media_2'] < 7.0) & (df['final_2'] >= 7.0)
    df['permaneceu_1'] = (df['media_1'] < 7.0) & (df['final_1'] < 7.0)
