df_boletim_full = load_full_data()

# --- SIDEBAR ---
st.sidebar.header("⚙️ Painel de Controle")
etapa_sel = st.sidebar.selectbox(
    "Selecione a Etapa",
    ["2ª Etapa (Atual)", "1ª Etapa", "Comparativo 1ª x 2ª"]
)

turma_opcoes = ["Todas as Turmas"] + sorted(df_boletim_full['turma'].unique().tolist())
turma_sel = st.sidebar.selectbox("Filtrar por Turma", turma_opcoes)

# Filtragem do dataframe base por turma
if turma_sel != "Todas as Turmas":
    df_filtered = df_boletim_full[df_boletim_full['turma'] == turma_sel].copy()
else:
    df_filtered = df_boletim_full.copy()

# Definir sufixos e nomes de colunas dinâmicos pela etapa selecionada
if etapa_sel == "1ª Etapa":
    col_med_orig = 'media_1'
    col_rp = 'rp_1'
    col_final = 'final_1'
    col_em_rp = 'em_rp_1'
    col_recup = 'recuperado_1'
    col_perm = 'permaneceu_1'
    col_abaixo5 = 'abaixo5_1'
    label_etapa = '1ª Etapa'
else:
    col_med_orig = 'media_2'
    col_rp = 'rp_2'
    col_final = 'final_2'
    col_em_rp = 'em_rp_2'
    col_recup = 'recuperado_2'
    col_perm = 'permaneceu_2'
    col_abaixo5 = 'abaixo5_2'
    label_etapa = '2ª Etapa'

# --- NAVEGAÇÃO POR ABAS ANALÍTICAS (AS 8 ABAS DO RELATÓRIO) ---
tabs = st.tabs([
    "📊 Resumo Executivo",
    "🧭 Diagnóstico por Turma",
    "📈 Eficiência RP",
    "📚 Disciplinas por Turma",
    "⚠️ Alunos em Risco",
    "🏆 Ranking Disciplinas",
    "👤 Análise por Aluno",
    "📋 Dados Completos"
])

# ==========================================
# ABA 1: 📊 Resumo Executivo
# ==========================================
with tabs[0]:
    st.subheader("📊 Resumo Executivo de Desempenho")
    
    tot_alunos = df_filtered['aluno'].nunique()
    tot_registros = len(df_filtered)
    
    # Alunos com RP na etapa
    al_rp = df_filtered[df_filtered[col_em_rp]].groupby('aluno').ngroups
    al_sem_rp = tot_alunos - al_rp
    
    # Registros
    reg_rp = df_filtered[col_em_rp].sum()
    reg_recup = df_filtered[col_recup].sum()
    
    # Saída total (Alunos que recuperaram 100% das suas RPs)
    st_rp_df = df_filtered.groupby('aluno').agg(
        total_rp=(col_em_rp, 'sum'),
        perm_rp=(col_perm, 'sum')
    ).reset_index()
    saida_total = len(st_rp_df[(st_rp_df['total_rp'] > 0) & (st_rp_df['perm_rp'] == 0)])

    # KPI Cards
    c1, c2, c3, c4, c5, c6 = st.columns(6)
    c1.metric("ALUNOS", tot_alunos, "base de estudantes")
    c2.metric("REGISTROS", tot_registros, "aluno x disciplina")
    c3.metric("ALUNOS COM RP", al_rp, f"{(al_rp/tot_alunos)*100:.2f}% do total")
    c4.metric("SEM RP", al_sem_rp, f"{(al_sem_rp/tot_alunos)*100:.2f}% aprovação direta")
    c5.metric("SAÍDA TOTAL RP", saida_total, f"{(saida_total/al_rp)*100:.2f}% dos impactados" if al_rp>0 else "0%")
    c6.metric("REG. RECUPERADOS", reg_recup, f"{(reg_recup/reg_rp)*100:.2f}% das RPs" if reg_rp>0 else "0%")

    st.markdown("---")
    st.subheader("Leitura Executiva do Período")
    
    med_orig_geral = df_filtered[col_med_orig].mean()
    med_fin_geral = df_filtered[col_final].mean()
    
    st.write(f"• **Média Geral de Notas:** A média geral dos registros originais foi de **{med_orig_geral:.2f}**, evoluindo para **{med_fin_geral:.2f}** após a aplicação da Recuperação Paralela (RP).")
    st.write(f"• **Incidência de RP:** Houve **{reg_rp} ocorrências de RP** ({ (reg_rp/tot_registros)*100:.2f}% do total de lançamentos acadêmicos).")
    st.write(f"• **Eficiência das Avaliações:** **{reg_recup} notas foram revertidas** com sucesso após as provas de apoio, representando **{(reg_recup/reg_rp)*100:.2f}%** de taxa de reversão.")

# ==========================================
# ABA 2: 🧭 Diagnóstico por Turma
# ==========================================
with tabs[1]:
    st.subheader("🧭 Diagnóstico por Turma (Visão por Registros Acadêmicos)")
    
    df_diag_turma = df_filtered.groupby('turma').agg(
        alunos=('aluno', 'nunique'),
        registros=('disciplina', 'count'),
        media_original=(col_med_orig, 'mean'),
        ocorrencias_rp=(col_em_rp, 'sum'),
        ocorrencias_abaixo5=(col_abaixo5, 'sum'),
        ocorrencias_recuperadas=(col_recup, 'sum')
    ).reset_index()
    
    df_diag_turma['pct_registros_rp'] = (df_diag_turma['ocorrencias_rp'] / df_diag_turma['registros']) * 100
    
    col_diag1, col_diag2 = st.columns([3, 2])
    
    with col_diag1:
        st.dataframe(
            df_diag_turma.rename(columns={
                'turma': 'Turma',
                'alunos': 'Alunos',
                'registros': 'Registros',
                'media_original': 'Média Original',
                'ocorrencias_rp': 'Ocorrências RP',
                'pct_registros_rp': '% Registros RP',
                'ocorrencias_abaixo5': 'Notas < 5,0',
                'ocorrencias_recuperadas': 'Recuperadas'
            }).style.format({
                'Média Original': '{:.2f}',
                '% Registros RP': '{:.2f}%'
            }),
            use_container_width=True
        )
        
    with col_diag2:
        fig_diag = px.bar(
            df_diag_turma, x='turma', y='pct_registros_rp',
            text_auto='.2f',
            title="% de Registros em RP por Turma",
            color='pct_registros_rp', color_continuous_scale='Reds'
        )
        fig_diag.update_layout(showlegend=False, yaxis_title="% em RP", xaxis_title="")
        st.plotly_chart(fig_diag, use_container_width=True)

# ==========================================
# ABA 3: 📈 Eficiência RP
# ==========================================
with tabs[2]:
    st.subheader("📈 Eficiência da Recuperação Paralela (RP)")
    
    df_efic_turma = df_filtered.groupby('turma').agg(
        ocorrencias_rp=(col_em_rp, 'sum'),
        recuperadas=(col_recup, 'sum'),
        permaneceram=(col_perm, 'sum'),
        media_original=(col_med_orig, 'mean'),
        media_final=(col_final, 'mean')
    ).reset_index()
    
